use umf_core::{Context,Limits,ResourceProfile,Utf16,Value,Diagnostic,Severity};
use umf_core::constraints::{prepare_program,execute_constraints};
fn get<'a>(v:&'a Value,k:&str)->&'a Value{if let Value::Object(m)=v{m.iter().find(|(n,_)|n==&Utf16::from(k)).map(|(_,v)|v).unwrap()}else{panic!("not object")}}
fn text(v:&Value)->Utf16{if let Value::String(s)=v{s.clone()}else{panic!("not text")}}
fn array(v:&Value)->&[Value]{if let Value::Array(v)=v{v}else{panic!("not array")}}
fn obj(v:Vec<(&str,Value)>)->Value{Value::Object(v.into_iter().map(|(k,v)|(Utf16::from(k),v)).collect())}
fn op(n:&str,args:Vec<Value>)->Value{obj(vec![("op",Value::string_utf8(n)),("args",Value::Array(args))])}
fn var(n:&str)->Value{obj(vec![("var",Value::string_utf8(n))])}
fn emit(code:&str,e:Value)->Value{obj(vec![("op",Value::string_utf8("emit")),("diagnostic",obj(vec![("code",Value::string_utf8(code)),("path",Value::string_utf8("")),("message",e),("severity",Value::string_utf8("error"))]))])}
fn diagnostic(v:&Value)->Diagnostic{let code=text(get(v,"code"));let path=text(get(v,"path"));let message=text(get(v,"message"));let origin=|t:&Utf16|umf_core::python_value::PyText::from_codepoints(t.units().iter().map(|u|*u as u32).collect()).unwrap();Diagnostic{python_text_origin:Some(umf_core::error::PythonDiagnosticText{code:Some(origin(&code)),path:Some(origin(&path)),message:Some(origin(&message))}),code,path,message,severity:if text(get(v,"severity"))==Utf16::from("warning"){Severity::Warning}else{Severity::Error},python_source_path:false}}
fn diagvalue(d:Diagnostic)->Value{obj(vec![("code",Value::String(d.code)),("path",Value::String(d.path)),("message",Value::String(d.message)),("severity",Value::string_utf8(if d.severity==Severity::Error{"error"}else{"warning"}))])}
struct Caps(Vec<Diagnostic>);impl umf_core::Capabilities for Caps{fn validate_extension(&mut self,_:u64,_:&Value,_:&umf_core::SemanticContext)->Result<Vec<Diagnostic>,Utf16>{Ok(self.0.clone())}}
fn main(){let p=std::env::args().nth(1).unwrap();let s=std::fs::read_to_string(&p).unwrap();let mut fixture_ctx=Context::with_limits(ResourceProfile::Cooperative,Limits{max_text_units:32_000_000,max_values:10_000_000,..Limits::ordinary()}).unwrap();let f=umf_core::serialization::read_json_value(&s.encode_utf16().collect::<Vec<_>>(),umf_core::serialization::Format::Json,&mut fixture_ctx).unwrap();let sr=umf_core::schema::SchemaResources::default();let ps=umf_core::schema::CompiledSchema::compile(&Value::Bool(true),&sr,&mut Context::ordinary()).unwrap();let mut reg=umf_core::Registry::new();reg.register(get(&f,"manifest"),Some(1),&ps,&sr,&mut Context::ordinary()).unwrap();let mut caps=Caps(array(get(&f,"callbackDiagnostics")).iter().map(diagnostic).collect());let mut mismatches=0;let cases=array(get(&f,"cases"));for c in cases{let mut steps=array(get(&f,"setup")).to_vec();steps.push(obj(vec![("op",Value::string_utf8("let")),("name",Value::string_utf8("result")),("value",get(c,"expression").clone())]));steps.push(emit("CANONICAL",op("canonical",vec![op("tuple",vec![var("result")])])));steps.push(emit("STRING",op("concat",vec![var("result")])));steps.push(emit("TRUTH",op("concat",vec![op("not",vec![var("result")])])));let p=obj(vec![("profile",Value::string_utf8("umf.constraints/1")),("steps",Value::Array(steps))]);let prepared=prepare_program(&p,&mut Context::ordinary()).unwrap();let actual=execute_constraints(get(&f,"document"),&prepared,get(&f,"policy"),&reg,&mut caps,&mut Context::ordinary());let expected=get(get(c,"expected"),"diagnostics");let actualvalue=actual.as_ref().ok().map(|d|Value::Array(d.iter().cloned().map(diagvalue).collect()));if actualvalue.as_ref()!=Some(expected){mismatches+=1;println!("{}\texpected={:?}\tactual={:?}",text(get(c,"id")).to_utf8().unwrap(),expected,actual);}}println!("cases={} mismatches={mismatches}",cases.len());}
